"},{"page":15,"start":20673,"end":21444,"sha256":"a179b3f6632356dfbf6ae21cffd0d1504c2a87af4700e0ef56cdf4777b2e58b2","extractionMethod":"native_pdf_text","reviewStatus":"extracted_unreviewed"},{"page":16,"start":21447,"end":23758,"sha256":"a5866bef7bd1c977177624581147bd5cfe6ec800e5d3853523e48478880e12f2","extractionMethod":"native_pdf_text","reviewStatus":"extracted_unreviewed"},{"page":17,"start":23761,"end":25523,"sha256":"50fb732995d00c9199054c6dcc9d0663aa36d9b62cfbfa98fd24d70c0a9c0e4a","extractionMethod":"native_pdf_text","reviewStatus":"extracted_unreviewed"},{"page":18,"start":25526,"end":27895,"sha256":"83acaa418388ad765ca260997b476cf2f690b756a2afbe69ced72e1cf1c54d16","extractionMethod":"native_pdf_text","reviewStatus":"extracted_unreviewed"},{"page":19,"start":27898,"end":30586,"sha256":"d06eb0aeeadc32a94d5356b7913b67be46d9f8017c65da4f45b53ef91cff96e4","extractionMethod":"native_pdf_text","reviewStatus":"extracted_unreviewed"},{"page":20,"start":30589,"end":33969,"sha256":"afb16af55e38c4f5a7eae0e9f1d3945716b756c2bc5788e1f64458f4a67553a0","extractionMethod":"native_pdf_text","reviewStatus":"extracted_unreviewed"},{"page":21,"start":33972,"end":36401,"sha256":"43c1c328198311e388a824bdd5627886794d10bc45a40ebeab88f733e224577f","extractionMethod":"native_pdf_text","reviewStatus":"extracted_unreviewed"},{"page":22,"start":36404,"end":38482,"sha256":"d2c8c30944d0b388c79627592791a348d90224e5d2ef7cfb921c18d89c5c63d8","extractionMethod":"native_pdf_text","reviewStatus":"extracted_unreviewed"},{"page":23,"start":38485,"end":40947,"sha256":"be773a35b6c0118468c13d1787b0787ae8e255755123dc33eb39fc80949892b2","extractionMethod":"native_pdf_text","reviewStatus":"extracted_unreviewed"},{"page":24,"start":40950,"end":42252,"sha256":"0c767c991882216e39bc9f0814fec134b11c14b28dcef62329bbb60a865bcb7e","extractionMethod":"native_pdf_text","reviewStatus":"extracted_unreviewed"},{"page":25,"start":42255,"end":44570,"sha256":"c418e54f4ce726ccf1123abfabb548678b1c9dad60401e8bc03d9e4502df