a256":"9aa5b0c533e93476216b1669f0ea4ac36880bcd092eaa5a7dc700584c4bbc4e4","extractionMethod":"native_pdf_text","reviewStatus":"extracted_unreviewed"},{"page":13,"start":33182,"end":35667,"sha256":"a52504499913f2eb47c341eb8b341d8fd95109d3da8cb5fbf5b7ec566d9f3f70","extractionMethod":"native_pdf_text","reviewStatus":"extracted_unreviewed"},{"page":14,"start":35670,"end":37167,"sha256":"9b400f6f265b76bec15014bb21ff81649b4d61933e302a5fd04b156efb7352ae","extractionMethod":"native_pdf_text","reviewStatus":"extracted_unreviewed"},{"page":15,"start":37170,"end":39648,"sha256":"d127b0f7a47e31f66b5615f2da5a86762108be6d0a0a04a892a5435021854089","extractionMethod":"native_pdf_text","reviewStatus":"extracted_unreviewed"},{"page":16,"start":39651,"end":41806,"sha256":"755f75fd8747679543cbdc16eda2fecf7793ef28f6192e089ce1d27ecfc1b022","extractionMethod":"native_pdf_text","reviewStatus":"extracted_unreviewed"},{"page":17,"start":41809,"end":43937,"sha256":"cf243a69692ce0ee0f4df19d9d18dc744b6281c9991382c38891e3941260eb5f","extractionMethod":"native_pdf_text","reviewStatus":"extracted_unreviewed"},{"page":18,"start":43940,"end":46419,"sha256":"11b9061f30c37827bba3f16885427b0fe83087a19895676a56281ac9987fb914","extractionMethod":"native_pdf_text","reviewStatus":"extracted_unreviewed"},{"page":19,"start":46422,"end":49482,"sha256":"58d44cfe762962f6802de875c5e13adf0f71c777b10d6e5ab6ffb800d9db670b","extractionMethod":"native_pdf_text","reviewStatus":"extracted_unreviewed"},{"page":20,"start":49485,"end":51006,"sha256":"b277450b9cdb55f266d77e9a910445f707621301902bdab2d2236a5427149498","extractionMethod":"native_pdf_text","reviewStatus":"extracted_unreviewed"},{"page":21,"start":51009,"end":54566,"sha256":"56dff9b24e92084264bb0bd22034e1012448dacef878c7ef38afde8433dacb97","extractionMethod":"native_pdf_text","reviewStatus":"extracted_unreviewed"},{"page":22,"start":54569,"end":57014,"sha256":"421c8b04385e5083549f86742dd159d7194094236572af130ffe1fbe7644acd1","extractionMethod":"native_pdf_text","reviewStatus":"extracted_unreviewed"},{"page":23,"start":57017,"end":60508,"sha256":"628a17b972414a52bf20d2a157e1be9928613a3ec739b70d817aadb756b0f4d7","extractionMethod":"native_pdf_text","reviewStatus":"extracted_unreviewed"},{"page":24,"start":60511,"end":63273,"sha256":"370337083ba2b537a63d63d0311f6cb175ff6b989528cc1795f548e7611edf7b","extractionMethod":"native_pdf_text","reviewStatus":"extracted_unreviewed"},{"page":25,"start":63276,"end":65233,"sha256":"f591774dd3e8eb236f3854db7850e7c12ea180a1dacfcbb9b9588d3796a61ee0","extractionMethod":"native_pdf_text","reviewStatus":"extracted_unreviewed"},{"page":26,"start":65236,"end":66635,"sha256":"773fdac4e67c7fd0071cc6370931850b9e79ad80f30df9fda87acd2d9d7c61b4","extractionMethod":"native_pdf_text","reviewStatus":"extracted_unreviewed"},{"page":27,"start":66638,"end":69630,"sha256":"bc4e7cc96e8ab97202d52a16e6a3a54c07f65b4b731cd3779c7f711c0f99a13f","extractionMethod":"native_pdf_text","reviewStatus":"extracted_unreviewed"},{"page":28,"start":69633,"end":72306,"sha256":"a9d6feb5250578e31010f182f2fb988248288d3020a2150bb163dac296e7c3e3","extractionMethod":"native_pdf_text","reviewStatus":"extracted_unreviewed"},{"page":29,"start":72309,"end":74096,"sha256":"5734ed8e140513c8869a2f800958a5f70f57e1e1343cd994fe26be45ac17a7f0","extractionMethod":"native_pdf_text","reviewStatus":"extracted_unreviewed"},{"page":30,"start":74099,"end":76950,"sha256":"5bb501d66ba1c95e13e3e838daf5a5cf9563104a0f866c67670a8c18f9f04e69","extractionMethod":"native_pdf_text","reviewStatus":"extracted_unreviewed"},{"page":31,"start":76953,"end":79887,"sha256":"d4bafc1b612e81ff6849064b837ca366b4d9d0562d7839533a475bfe8edaef96","extractionMethod":"native_pdf_text","reviewStatus":"extracted_unreviewed"},{"page":32,"start":79890,"end":81612,"sha256":"b784aec7188c196885e0f2af0608de5da75aa0f2add3301d25fd66677740058f","extractionMethod":"native_pdf_text","reviewStatus":"extracted_unreviewed"},{"page":33,"start":81615,"end":83740,"sha256":"99d2e533b7777b686688ccb7