d":19000,"sha256":"6b3d05a718f155a31e9089cac06982687220c45306f19be15c33f1a6ff88df2b","extractionMethod":"native_pdf_text","reviewStatus":"extracted_unreviewed"},{"page":14,"start":19003,"end":21231,"sha256":"5c6fd52fed18bc3feaa16f0ae2599cd355dc5e973892e634ed06d28505864360","extractionMethod":"native_pdf_text","reviewStatus":"extracted_unreviewed"},{"page":15,"start":21234,"end":23641,"sha256":"75d1a11554519cea18a8f6e9cd88863e0a5131c4660e63f119993017d9e29f21","extractionMethod":"native_pdf_text","reviewStatus":"extracted_unreviewed"},{"page":16,"start":23644,"end":24216,"sha256":"82226299730bf9eada0f268ba9958bc2e1b7ad69e8e6911b3c30cb063f66b9f5","extractionMethod":"native_pdf_text","reviewStatus":"extracted_unreviewed"},{"page":17,"start":24219,"end":24879,"sha256":"49f1892cfec7cd3934aec980c3c3e545c327532398ec11e156b370ff29433528","extractionMethod":"native_pdf_text","reviewStatus":"extracted_unreviewed"},{"page":18,"start":24882,"end":26576,"sha256":"a4d494d746f3bda29bc85feda48dae137a01b76153dcba2999bc3f4d392777e0","extractionMethod":"native_pdf_text","reviewStatus":"extracted_unreviewed"},{"page":19,"start":26579,"end":27524,"sha256":"2ee7454f3773bf0ac90db83a18ee400aa87b68ffc976d5ee7b762398a8cd99ab","extractionMethod":"native_pdf_text","reviewStatus":"extracted_unreviewed"},{"page":20,"start":27527,"end":28971,"sha256":"ad871ed65eb264fa008a66fa34547b30f6f0a3ab996f03d6848a23c821a858cc","extractionMethod":"native_pdf_text","reviewStatus":"extracted_unreviewed"},{"page":21,"start":28974,"end":30714,"sha256":"4cf28d1f5a7cb55c797975365adfec3eb828bec255ad4b06e502af0a0f1ef621","extractionMethod":"native_pdf_text","reviewStatus":"extracted_unreviewed"},{"page":22,"start":30717,"end":33294,"sha256":"b99b31914ee0f6ecaa51fac2343449b9acb1659ec4d031050d19ec7368593c28","extractionMethod":"native_pdf_text","reviewStatus":"extracted_unreviewed"},{"page":23,"start":33297,"end":35283,"sha256":"a8d44c02eb2e8daa10b072f2a620bf1ff7c8bbb243e26892310b7eb1f01fc3aa","extractionMethod":"nativ